import{_ as t,c as r,o as s,aj as a}from"./chunks/framework.CSCBGoZg.js";const m=JSON.parse('{"title":"Docker Secrets","description":"","frontmatter":{},"headers":[],"relativePath":"reference/pipeline-step-docker-secrets.md","filePath":"reference/pipeline-step-docker-secrets.md","lastUpdated":0}'),o={name:"reference/pipeline-step-docker-secrets.md"};function c(d,e,i,n,l,h){return s(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="docker-secrets" tabindex="-1">Docker Secrets <a class="header-anchor" href="#docker-secrets" aria-label="Permalink to “Docker Secrets”">​</a></h1><div style="display:flex;flex-wrap:wrap;gap:.5em;margin:1.6em 0 -.3em;"><a href="https://hub.docker.com/r/reeveci/step-docker-secrets" target="_blank"><img alt="Docker Image Size" src="https://img.shields.io/docker/image-size/reeveci/step-docker-secrets?logo=docker&amp;label=reeveci%2Fstep-docker-secrets"></a><a href="https://github.com/reeveci/step-docker-secrets/blob/main/LICENSE" target="_blank"><img alt="License" src="https://img.shields.io/github/license/reeveci/step-docker-secrets?color=%239944ee"></a><a href="https://github.com/reeveci/step-docker-secrets" target="_blank"><img alt="Git Repository" src="https://img.shields.io/github/stars/reeveci/step-docker-secrets?label=Source"></a></div><p>Sets up a Docker volume with secret files.</p><p>This step creates a volume that contains secret files similar to how <a href="https://docs.docker.com/engine/swarm/secrets/" target="_blank" rel="noreferrer">Docker secrets</a> work. Howether, it uses generic Docker volumes for this purpose, which allows changing their contents even while they are being used by running services.</p><p>The step sets a runtime variable that changes whenever the volume&#39;s contents are updated. This can be used to automatically redeploy services when the secrets change.</p><h2 id="params" tabindex="-1">Params <a class="header-anchor" href="#params" aria-label="Permalink to “Params”">​</a></h2><table tabindex="0"><thead><tr><th>Param</th><th>Description</th></tr></thead><tbody><tr><td><code>VOLUME</code></td><td>Name of the volume (<code>string</code>)</td></tr><tr><td><code>TARGET_UID</code></td><td>User ID owning the files (default: <code>1000</code>) (<code>number</code>)</td></tr><tr><td><code>TARGET_GID</code></td><td>Group ID owning the files (default: <code>1000</code>) (<code>number</code>)</td></tr><tr><td><code>FILE_MODE</code></td><td>Mode to apply to the secrets (default: <code>0440</code>) (<code>number</code>)</td></tr><tr><td><code>REVISION_VAR</code></td><td>Name of a runtime variable for setting the volume&#39;s revision to - this value can for example be applied to related containers as an environment variable in order to automatically update them when a secret changes (default: <code>SECRET_REV</code>) (<code>string</code>)</td></tr><tr><td><code>SECRET_&lt;name&gt;</code></td><td>Names and values of the secrets to be written to the volume (<code>string</code>)</td></tr><tr><td><code>SECRETFILE_&lt;name&gt;</code></td><td>Names and paths to the secrets to be written to the volume (<code>string</code>)</td></tr></tbody></table><h2 id="trust" tabindex="-1">Trust <a class="header-anchor" href="#trust" aria-label="Permalink to “Trust”">​</a></h2><p>This step requires access to the Docker socket. See <a href="/guide/trusted-tasks">Trusted Tasks</a> for more information.</p>',9)])])}const u=t(o,[["render",c]]);export{m as __pageData,u as default};
